    internal sealed class VerificationInvariantRecord
    {
        public string Id { get; set; }
        public string ModelId { get; set; }
        public string Kind { get; set; }
        public string Formula { get; set; }
        public string Status { get; set; }
        public string CreatedUtc { get; set; }
        public string UpdatedUtc { get; set; }
        public double StructuralScore { get; set; }
        public string SourceModelFingerprint { get; set; }
        public override string ToString() { return (Status ?? "CANDIDATE") + "   ·   " + (Kind ?? "INVARIANT") + "   ·   " + StructuralScore.ToString("0.000", CultureInfo.InvariantCulture) + "   ·   " + (Formula ?? "∅"); }
    }

    internal sealed class VerificationMutationResult
    {
        public string MutationId { get; set; }
        public string Kind { get; set; }
        public string SubjectId { get; set; }
        public string Description { get; set; }
        public string Outcome { get; set; }
        public int ChangedProperties { get; set; }
        public List<string> ChangedPropertyIds { get; set; }
        public VerificationMutationResult() { ChangedPropertyIds = new List<string>(); }
        public override string ToString() { return (Outcome ?? "SURVIVED").PadRight(10) + "   ·   " + (Kind ?? "MUTATION").PadRight(20) + "   ·   changed " + ChangedProperties.ToString(CultureInfo.InvariantCulture).PadLeft(3) + "   ·   " + (Description ?? SubjectId ?? "∅"); }
    }

    internal sealed class VerificationMutationCampaign
    {
        public string Id { get; set; }
        public string ModelId { get; set; }
        public string CreatedUtc { get; set; }
        public string ModelFingerprint { get; set; }
        public int Mutants { get; set; }
        public int Killed { get; set; }
        public int Survived { get; set; }
        public double MutationScore { get; set; }
        public List<VerificationMutationResult> Results { get; set; }
        public VerificationMutationCampaign() { Results = new List<VerificationMutationResult>(); }
        public override string ToString() { return MutationScore.ToString("P1", CultureInfo.InvariantCulture) + "   ·   " + Killed.ToString(CultureInfo.InvariantCulture) + " killed / " + Survived.ToString(CultureInfo.InvariantCulture) + " survived   ·   " + (CreatedUtc ?? ""); }
    }

