        private static string CensusLine() { return Store.Models.Count(m => Active(m.Status)).ToString(CultureInfo.InvariantCulture) + " active models · " + Store.Models.Sum(m => m.States.Count).ToString(CultureInfo.InvariantCulture) + " states · " + Store.Models.Sum(m => m.Transitions.Count).ToString(CultureInfo.InvariantCulture) + " transitions · " + Store.Properties.Count(p => Active(p.Status)).ToString(CultureInfo.InvariantCulture) + " active properties · " + Store.Runs.Count.ToString(CultureInfo.InvariantCulture) + " certificates · " + Store.Invariants.Count(i => Active(i.Status)).ToString(CultureInfo.InvariantCulture) + " retained invariants"; }
        private static bool Active(string status) { return !String.Equals(status, "ARCHIVED", StringComparison.OrdinalIgnoreCase) && !String.Equals(status, "DISABLED", StringComparison.OrdinalIgnoreCase) && !String.Equals(status, "RETRACTED", StringComparison.OrdinalIgnoreCase); }

