        private static void CreateModelPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            string name = Prompt(owner, "FORGE MODEL", "Model name", "Protocol " + DateTime.Now.ToString("yyyy-MM-dd HHmm", CultureInfo.InvariantCulture)); if (String.IsNullOrWhiteSpace(name)) return; string description = PromptLarge(owner, "MODEL CHARTER", "Describe the protocol boundary, abstraction and verification purpose", "Finite abstraction. State labels are propositions; transitions encode possible next steps."); if (description == null) return; VerificationModel model = new VerificationModel { Id = Id("model"), Name = Short(name.Trim(), 240), Description = Short(description, MaxLongText), Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1 }; VerificationState initial = new VerificationState { Id = Id("state"), Name = "initial", Description = "Initial state", Status = "ACTIVE" }; initial.Labels.Add("phase:initial"); model.States.Add(initial); model.InitialStateIds.Add(initial.Id); Store.Models.Insert(0, model); TrimStore(); Save(ctx); AppendLedger(ctx, "MODEL_FORGED", model.Id, model.Name, VerificationKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

        private static void ImportDslPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            string name = Prompt(owner, "IMPORT TRANSITION DSL", "Model name", "Mutual exclusion protocol"); if (String.IsNullOrWhiteSpace(name)) return; string sample = "# STATE name | comma labels | key=value;key=value\r\nSTATE idle | phase:idle, safe | owner=none\r\nSTATE requesting | phase:request, safe | owner=none\r\nSTATE critical | phase:critical, has_lock | owner=client\r\nINITIAL idle\r\nTRANS request | idle -> requesting | COMMAND | request received | enqueue | weak-fair\r\nTRANS grant | requesting -> critical | AUTHORITY | lock free | acquire | strong-fair\r\nTRANS release | critical -> idle | COMMAND | work complete | release | weak-fair"; string dsl = PromptLarge(owner, "STATE-TRANSITION DSL", "STATE name | labels | properties; INITIAL state; TRANS name | from -> to | kind | guard | action | fairness", sample); if (String.IsNullOrWhiteSpace(dsl)) return; string error; VerificationModel model = ParseDsl(name, dsl, out error); if (model == null) { MessageBox.Show(owner, error ?? "DSL could not be parsed.", "YOMI · Protocol Forge"); return; } Store.Models.Insert(0, model); TrimStore(); Save(ctx); AppendLedger(ctx, "MODEL_DSL_IMPORTED", model.Id, model.Name + " · " + model.States.Count + " states · " + model.Transitions.Count + " transitions", VerificationKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

        private static VerificationModel ParseDsl(string name, string dsl, out string error)
        {
            error = null; VerificationModel model = new VerificationModel { Id = Id("model"), Name = Short(name, 240), Description = "Imported state-transition DSL", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1 }; Dictionary<string, VerificationState> byName = new Dictionary<string, VerificationState>(StringComparer.OrdinalIgnoreCase); List<string> initialNames = new List<string>(); List<DslTransition> transitions = new List<DslTransition>(); int lineNumber = 0; foreach (string raw in (dsl ?? "").Replace("\r", "").Split('\n')) { lineNumber++; string line = raw.Trim(); if (line.Length == 0 || line.StartsWith("#", StringComparison.Ordinal)) continue; if (line.StartsWith("STATE ", StringComparison.OrdinalIgnoreCase)) { string[] parts = line.Substring(6).Split('|'); string stateName = parts[0].Trim(); if (String.IsNullOrWhiteSpace(stateName)) { error = "Line " + lineNumber + ": state name is empty."; return null; } if (byName.ContainsKey(stateName)) { error = "Line " + lineNumber + ": duplicate state '" + stateName + "'."; return null; } VerificationState state = new VerificationState { Id = Id("state"), Name = Short(stateName, 180), Description = "DSL state", Status = "ACTIVE" }; if (parts.Length > 1) state.Labels = parts[1].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxLabelsPerState).ToList(); if (parts.Length > 2) foreach (string property in parts[2].Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)) { int equals = property.IndexOf('='); if (equals > 0) state.Properties[Short(property.Substring(0, equals).Trim(), 128)] = Short(property.Substring(equals + 1).Trim(), 512); } byName[stateName] = state; model.States.Add(state); continue; } if (line.StartsWith("INITIAL ", StringComparison.OrdinalIgnoreCase)) { initialNames.AddRange(line.Substring(8).Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim())); continue; } if (line.StartsWith("TRANS ", StringComparison.OrdinalIgnoreCase)) { string[] parts = line.Substring(6).Split('|'); if (parts.Length < 2) { error = "Line " + lineNumber + ": transition requires name | from -> to."; return null; } string[] endpoints = parts[1].Split(new[] { "->" }, StringSplitOptions.None); if (endpoints.Length != 2) { error = "Line " + lineNumber + ": transition endpoints require from -> to."; return null; } transitions.Add(new DslTransition { Line = lineNumber, Name = parts[0].Trim(), From = endpoints[0].Trim(), To = endpoints[1].Trim(), Kind = parts.Length > 2 ? parts[2].Trim() : "STEP", Guard = parts.Length > 3 ? parts[3].Trim() : "", Action = parts.Length > 4 ? parts[4].Trim() : "", Fairness = parts.Length > 5 ? parts[5].Trim() : "" }); continue; } error = "Line " + lineNumber + ": expected STATE, INITIAL or TRANS."; return null; }
            if (model.States.Count == 0) { error = "The DSL defines no states."; return null; } foreach (string initialName in initialNames.Distinct(StringComparer.OrdinalIgnoreCase)) { VerificationState state; if (!byName.TryGetValue(initialName, out state)) { error = "Initial state '" + initialName + "' is undefined."; return null; } model.InitialStateIds.Add(state.Id); } if (model.InitialStateIds.Count == 0) model.InitialStateIds.Add(model.States[0].Id); foreach (DslTransition row in transitions) { VerificationState from, to; if (!byName.TryGetValue(row.From, out from) || !byName.TryGetValue(row.To, out to)) { error = "Line " + row.Line + ": transition references an undefined state."; return null; } model.Transitions.Add(new VerificationTransition { Id = Id("transition"), Name = Short(row.Name, 180), FromStateId = from.Id, ToStateId = to.Id, Kind = Short(String.IsNullOrWhiteSpace(row.Kind) ? "STEP" : row.Kind, 80), Guard = Short(row.Guard, 2048), Action = Short(row.Action, 2048), FairnessGroup = Short(row.Fairness, 180) }); } if (model.States.Count > MaxStatesPerModel || model.Transitions.Count > MaxTransitionsPerModel) { error = "Model exceeds bounded state or transition capacity."; return null; } return model;
        }

        private static void OpenModel(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            VerificationTopology topology = VerificationKernel.AnalyzeTopology(model, new VerificationKernelLimits()); Window w = W(owner, "YOMI · VERIFICATION MODEL · " + model.Name, 1240, 840); DockPanel root = Shell((model.Status ?? "ACTIVE") + " · " + model.Name, (model.Description ?? "") + "\r\nFingerprint " + VerificationKernel.Fingerprint(model) + (String.IsNullOrWhiteSpace(model.SourceFingerprint) ? "" : " · source " + Short(model.SourceFingerprint, 20)) + " · reachable " + topology.ReachableStates + "/" + topology.TotalStates + " · deadlocks " + topology.Deadlocks + " · SCCs " + topology.StrongComponents); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("CHECK CTL", delegate { CheckFormulaPrompt(w, ctx, index, model); })); tools.Children.Add(Btn("ADD STATE", delegate { AddStatePrompt(w, ctx, model); })); tools.Children.Add(Btn("ADD TRANSITION", delegate { AddTransitionPrompt(w, ctx, model); })); tools.Children.Add(Btn("PROPERTIES", delegate { OpenProperties(w, ctx, index, model); })); tools.Children.Add(Btn("TOPOLOGY", delegate { OpenTopology(w, ctx, index, model); })); tools.Children.Add(Btn("SYNTHESIZE INVARIANTS", delegate { OpenInvariantSynthesis(w, ctx, index, model); })); tools.Children.Add(Btn("VERIFY MATRIX", delegate { OpenVerificationMatrix(w, ctx, index, model); })); tools.Children.Add(Btn("CYBERNETIC TWIN", delegate { CyberneticDigitalTwinMetastructure.OpenFromVerificationModel(w, ctx, index, model); })); tools.Children.Add(Btn("COMPLEX POPULATION", delegate { ComplexSystemsLaboratory.OpenFromVerificationModel(w, ctx, index, model); })); tools.Children.Add(Btn("OPTIMIZE PROTOCOL", delegate { OperationsResearchEmpire.OpenFromVerificationModel(w, ctx, index, model); })); tools.Children.Add(Btn("STRATEGY PROJECTION", delegate { CounterfactualStrategySuperstructure.OpenFromVerificationModel(w, ctx, index, model); })); tools.Children.Add(Btn("CONFORMANCE PROTOCOL", delegate { ScientificDiscoveryHyperstructure.OpenFromVerificationModel(w, ctx, index, model); })); tools.Children.Add(Btn("FORK MODEL", delegate { ForkModel(w, ctx, index, model); })); tools.Children.Add(Btn(Active(model.Status) ? "ARCHIVE" : "RESTORE", delegate { model.Status = Active(model.Status) ? "ARCHIVED" : "ACTIVE"; Touch(model); Save(ctx); AppendLedger(ctx, "MODEL_" + model.Status, model.Id, model.Name, VerificationKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, model.Name, model, StorePath(ctx), "$models:" + model.Id, "VERIFICATION REACTOR › MODEL"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); Grid body = new Grid(); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); ListBox states = List(); states.ItemsSource = model.States.OrderBy(s => model.InitialStateIds.Contains(s.Id, StringComparer.OrdinalIgnoreCase) ? 0 : 1).ThenBy(s => s.Name).ToList(); states.MouseDoubleClick += delegate { VerificationState state = states.SelectedItem as VerificationState; if (state != null) OpenState(w, ctx, index, model, state); }; ListBox transitions = List(); transitions.ItemsSource = model.Transitions.OrderBy(t => t.Name).ToList(); transitions.MouseDoubleClick += delegate { VerificationTransition transition = transitions.SelectedItem as VerificationTransition; if (transition != null) OpenTransition(w, ctx, index, model, transition); }; Grid.SetColumn(states, 0); Grid.SetColumn(transitions, 1); body.Children.Add(states); body.Children.Add(transitions); root.Children.Add(body); w.Content = root; w.Show();
        }

        private static void AddStatePrompt(Window owner, DeepSystemsContext ctx, VerificationModel model)
        {
            if (model.States.Count >= MaxStatesPerModel) { MessageBox.Show(owner, "Model state bound reached.", "YOMI · Protocol Forge"); return; } string name = Prompt(owner, "ADD STATE", "State name", "state_" + (model.States.Count + 1).ToString(CultureInfo.InvariantCulture)); if (String.IsNullOrWhiteSpace(name)) return; string labels = Prompt(owner, "STATE LABELS", "Comma-separated atomic propositions", "phase:" + NormalizeSymbol(name)); if (labels == null) return; string properties = PromptLarge(owner, "STATE PROPERTIES", "One key=value per line or semicolon", ""); if (properties == null) return; VerificationState state = new VerificationState { Id = Id("state"), Name = Short(name.Trim(), 180), Description = "Operator-authored state", Status = "ACTIVE", Labels = labels.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxLabelsPerState).ToList() }; foreach (string row in SplitRows(properties)) { int equals = row.IndexOf('='); if (equals > 0) state.Properties[Short(row.Substring(0, equals).Trim(), 128)] = Short(row.Substring(equals + 1).Trim(), 512); } model.States.Add(state); string initial = Choose(owner, "INITIAL STATE", "Should this state also be an initial state?", new[] { "NO", "YES" }, "NO"); if (initial == "YES") model.InitialStateIds.Add(state.Id); Touch(model); Save(ctx); AppendLedger(ctx, "STATE_ADDED", state.Id, model.Id + " · " + state.Name, VerificationKernel.Fingerprint(model), "");
        }

        private static void AddTransitionPrompt(Window owner, DeepSystemsContext ctx, VerificationModel model)
        {
            if (model.Transitions.Count >= MaxTransitionsPerModel || model.States.Count == 0) return; VerificationState from = ChooseObject(owner, "TRANSITION ORIGIN", "Select origin state", model.States.Cast<object>().ToList()) as VerificationState; if (from == null) return; VerificationState to = ChooseObject(owner, "TRANSITION DESTINATION", "Select destination state", model.States.Cast<object>().ToList()) as VerificationState; if (to == null) return; string name = Prompt(owner, "ADD TRANSITION", "Transition/event name", "step"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "TRANSITION KIND", "Semantic class", new[] { "STEP", "COMMAND", "AUTHORITY", "RECOVERY", "TIMEOUT", "ENVIRONMENT", "INTERNAL" }, "STEP"); if (String.IsNullOrWhiteSpace(kind)) return; string guard = Prompt(owner, "TRANSITION GUARD", "Human-readable enabling condition", ""); if (guard == null) return; string action = Prompt(owner, "TRANSITION ACTION", "Human-readable state effect", ""); if (action == null) return; VerificationTransition transition = new VerificationTransition { Id = Id("transition"), FromStateId = from.Id, ToStateId = to.Id, Name = Short(name.Trim(), 180), Kind = kind, Guard = Short(guard, 2048), Action = Short(action, 2048) }; model.Transitions.Add(transition); Touch(model); Save(ctx); AppendLedger(ctx, "TRANSITION_ADDED", transition.Id, model.Id + " · " + from.Name + " → " + to.Name, VerificationKernel.Fingerprint(model), "");
        }

        private static void OpenState(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model, VerificationState state)
        {
            bool initial = model.InitialStateIds.Contains(state.Id, StringComparer.OrdinalIgnoreCase); Window w = W(owner, "YOMI · VERIFICATION STATE · " + state.Name, 1080, 740); DockPanel root = Shell((initial ? "INITIAL · " : "") + (state.Status ?? "ACTIVE") + " · " + state.Name, state.Id + " · model " + model.Name); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn(initial ? "REMOVE INITIAL" : "MAKE INITIAL", delegate { if (initial && model.InitialStateIds.Count > 1) model.InitialStateIds.RemoveAll(id => String.Equals(id, state.Id, StringComparison.OrdinalIgnoreCase)); else if (!initial) model.InitialStateIds.Add(state.Id); Touch(model); Save(ctx); AppendLedger(ctx, "STATE_INITIAL_CHANGED", state.Id, initial ? "REMOVED" : "ADDED", VerificationKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("EDIT LABELS", delegate { string raw = Prompt(w, "EDIT LABELS", "Comma-separated atomic propositions", String.Join(", ", state.Labels.ToArray())); if (raw != null) { state.Labels = raw.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxLabelsPerState).ToList(); Touch(model); Save(ctx); AppendLedger(ctx, "STATE_LABELS_EDITED", state.Id, String.Join(",", state.Labels.ToArray()), VerificationKernel.Fingerprint(model), ""); } })); tools.Children.Add(Btn("ADD EVIDENCE", delegate { AddEvidencePrompt(w, ctx, index, model, state.EvidenceNodeIds, state.Id); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, state.Name, state, StorePath(ctx), "$models:" + model.Id + ":states:" + state.Id, "VERIFICATION REACTOR › STATE"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); StringBuilder s = new StringBuilder(); s.AppendLine("STATE ID        " + state.Id); s.AppendLine("INITIAL         " + initial); s.AppendLine("STATUS          " + state.Status); s.AppendLine("LABELS          " + String.Join(", ", state.Labels.ToArray())); s.AppendLine("INCOMING        " + model.Transitions.Count(t => String.Equals(t.ToStateId, state.Id, StringComparison.OrdinalIgnoreCase))); s.AppendLine("OUTGOING        " + model.Transitions.Count(t => String.Equals(t.FromStateId, state.Id, StringComparison.OrdinalIgnoreCase))); s.AppendLine("EVIDENCE        " + state.EvidenceNodeIds.Count); s.AppendLine(); s.AppendLine("PROPERTIES"); foreach (KeyValuePair<string, string> p in state.Properties.OrderBy(x => x.Key)) s.AppendLine("  " + p.Key + " = " + p.Value); s.AppendLine(); s.AppendLine("DESCRIPTION"); s.AppendLine(state.Description ?? ""); TextBox details = ReadOnly(s.ToString()); DockPanel.SetDock(details, Dock.Top); root.Children.Add(details); ListBox evidence = EvidenceList(w, ctx, index, state.EvidenceNodeIds); evidence.MaxHeight = 210; root.Children.Add(evidence); w.Content = root; w.Show();
        }

        private static void OpenTransition(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model, VerificationTransition transition)
        {
            VerificationState from = State(model, transition.FromStateId), to = State(model, transition.ToStateId); Window w = W(owner, "YOMI · TRANSITION · " + transition.Name, 1080, 720); DockPanel root = Shell((transition.Status ?? "ACTIVE") + " · " + (transition.Kind ?? "STEP") + " · " + transition.Name, (from == null ? transition.FromStateId : from.Name) + " → " + (to == null ? transition.ToStateId : to.Name)); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("ADD EVIDENCE", delegate { AddEvidencePrompt(w, ctx, index, model, transition.EvidenceNodeIds, transition.Id); })); tools.Children.Add(Btn("DISABLE / ENABLE", delegate { transition.Status = String.Equals(transition.Status, "DISABLED", StringComparison.OrdinalIgnoreCase) ? "ACTIVE" : "DISABLED"; Touch(model); Save(ctx); AppendLedger(ctx, "TRANSITION_STATUS_CHANGED", transition.Id, transition.Status, VerificationKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, transition.Name, transition, StorePath(ctx), "$models:" + model.Id + ":transitions:" + transition.Id, "VERIFICATION REACTOR › TRANSITION"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); StringBuilder s = new StringBuilder(); s.AppendLine("TRANSITION ID   " + transition.Id); s.AppendLine("FROM            " + (from == null ? transition.FromStateId : from.Name + " · " + from.Id)); s.AppendLine("TO              " + (to == null ? transition.ToStateId : to.Name + " · " + to.Id)); s.AppendLine("STATUS          " + transition.Status); s.AppendLine("KIND            " + transition.Kind); s.AppendLine("FAIRNESS        " + (transition.FairnessGroup ?? "∅")); s.AppendLine("GUARD           " + (transition.Guard ?? "∅")); s.AppendLine("ACTION          " + (transition.Action ?? "∅")); s.AppendLine("EVIDENCE        " + transition.EvidenceNodeIds.Count); TextBox details = ReadOnly(s.ToString()); DockPanel.SetDock(details, Dock.Top); root.Children.Add(details); ListBox evidence = EvidenceList(w, ctx, index, transition.EvidenceNodeIds); root.Children.Add(evidence); w.Content = root; w.Show();
        }

        private static void AddEvidencePrompt(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model, List<string> destination, string subjectId)
        {
            string query = Prompt(owner, "ADD WORLD EVIDENCE", "Exact World URN or YQL; the highest-degree result becomes the anchor", "STATS"); if (String.IsNullOrWhiteSpace(query)) return; WorldNode node; if (!index.Nodes.TryGetValue(query.Trim(), out node)) node = WorldKernel.ExternalQuery(index, query.Trim()).Nodes.OrderByDescending(n => WorldKernel.ExternalDegree(index, n.Id)).FirstOrDefault(); if (node == null) { MessageBox.Show(owner, "No World Kernel object resolved.", "YOMI · Verification Evidence"); return; } destination.Add(node.Id); List<string> unique = destination.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); destination.Clear(); destination.AddRange(unique); Touch(model); Save(ctx); AppendLedger(ctx, "EVIDENCE_ANCHORED", subjectId, node.Id, VerificationKernel.Fingerprint(model), "");
        }

        private static void OpenProperties(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel scope)
        {
            Window w = W(owner, "YOMI · PROPERTY ARSENAL", 1200, 790); DockPanel root = Shell((scope == null ? "GLOBAL" : scope.Name) + " · FORMAL PROPERTY ARSENAL", "CTL obligations retain model identity, kind, severity and lifecycle. Passing proves only the bounded abstraction encoded by that model."); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("AUTHOR PROPERTY", delegate { VerificationModel model = scope ?? ChooseModel(w); if (model != null) CreatePropertyPrompt(w, ctx, index, model); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); IEnumerable<VerificationProperty> source = Store.Properties; if (scope != null) source = source.Where(p => String.Equals(p.ModelId, scope.Id, StringComparison.OrdinalIgnoreCase)); ListBox list = List(); list.ItemsSource = source.OrderBy(p => Active(p.Status) ? 0 : 1).ThenBy(p => p.Severity).ThenBy(p => p.Name).ToList(); list.MouseDoubleClick += delegate { VerificationProperty property = list.SelectedItem as VerificationProperty; if (property != null) OpenProperty(w, ctx, index, property); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void CreatePropertyPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            string name = Prompt(owner, "AUTHOR PROPERTY", "Property name", "Safety invariant"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "PROPERTY KIND", "Intent classification", new[] { "SAFETY", "LIVENESS", "REACHABILITY", "RECURRENCE", "FAIRNESS", "PROTOCOL" }, "SAFETY"); if (String.IsNullOrWhiteSpace(kind)) return; string severity = Choose(owner, "PROPERTY SEVERITY", "Obligation strength", new[] { "REQUIRED", "CRITICAL", "DESIRED", "EXPERIMENTAL" }, "REQUIRED"); if (String.IsNullOrWhiteSpace(severity)) return; string formula = Prompt(owner, "CTL FORMULA", "Atoms, !, &, |, ->, EX, AX, EF, AF, EG, AG, EU(left,right), AU(left,right)", kind == "LIVENESS" ? "AF phase:complete" : "AG safe"); if (String.IsNullOrWhiteSpace(formula)) return; TemporalFormula parsed; string error; if (!TemporalFormulaParser.TryParse(formula, 96, out parsed, out error)) { MessageBox.Show(owner, error, "YOMI · CTL Parser"); return; } VerificationProperty property = new VerificationProperty { Id = Id("property"), ModelId = model.Id, Name = Short(name, 240), Formula = Short(formula, MaxShortText), Kind = kind, Severity = severity, Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now() }; Store.Properties.Insert(0, property); TrimStore(); Save(ctx); AppendLedger(ctx, "PROPERTY_AUTHORED", property.Id, property.Name + " · " + parsed.Display, VerificationKernel.Fingerprint(model), ""); OpenProperty(owner, ctx, index, property);
        }

        private static void OpenProperty(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationProperty property)
        {
            VerificationModel model = Model(property.ModelId); Window w = W(owner, "YOMI · PROPERTY · " + property.Name, 1120, 740); DockPanel root = Shell((property.Status ?? "ACTIVE") + " · " + (property.Kind ?? "CTL") + " · " + property.Name, (property.Severity ?? "REQUIRED") + " · model " + (model == null ? property.ModelId : model.Name) + "\r\n" + property.Formula); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("VERIFY", delegate { if (model != null) RunProperty(w, ctx, index, model, property, true); })); tools.Children.Add(Btn(Active(property.Status) ? "DISABLE" : "ENABLE", delegate { property.Status = Active(property.Status) ? "DISABLED" : "ACTIVE"; property.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "PROPERTY_" + property.Status, property.Id, property.Name, model == null ? "" : VerificationKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, property.Name, property, StorePath(ctx), "$properties:" + property.Id, "VERIFICATION REACTOR › PROPERTY"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox runs = List(); runs.ItemsSource = Store.Runs.Where(r => String.Equals(r.PropertyId, property.Id, StringComparison.OrdinalIgnoreCase)).OrderByDescending(r => r.CheckedUtc).ToList(); runs.MouseDoubleClick += delegate { VerificationRun run = runs.SelectedItem as VerificationRun; if (run != null) OpenRun(w, ctx, index, run); }; root.Children.Add(runs); w.Content = root; w.Show();
        }

        private static void CheckFormulaPrompt(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            if (model == null) return; string initial = Store.FormulaHistory.FirstOrDefault() ?? "AG safe"; string formula = Prompt(owner, "CTL TRIBUNAL", "Formula over state labels/properties", initial); if (String.IsNullOrWhiteSpace(formula)) return; VerificationProperty transient = new VerificationProperty { Id = Id("adhoc"), ModelId = model.Id, Name = "Ad hoc · " + Short(formula, 80), Formula = formula, Kind = "AD HOC", Severity = "EXPERIMENTAL", Status = "TRANSIENT" }; RunProperty(owner, ctx, index, model, transient, true);
        }

        private static VerificationRun RunProperty(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model, VerificationProperty property, bool open)
        {
            VerificationCheckResult check = VerificationKernel.Check(model, property.Formula, new VerificationKernelLimits()); VerificationTopology topology = VerificationKernel.AnalyzeTopology(model, new VerificationKernelLimits()); VerificationRun run = new VerificationRun { Id = Id("run"), ModelId = model.Id, PropertyId = property.Id, PropertyName = property.Name, Formula = property.Formula, NormalizedFormula = check.NormalizedFormula, Outcome = !check.Parsed ? "ERROR" : check.Passed ? "PASS" : "FAIL", CheckedUtc = Now(), ModelFingerprint = check.ModelFingerprint, CertificateHash = check.CertificateHash, Diagnostic = check.Error ?? check.TraceKind, ReachableStates = topology.ReachableStates, SatisfyingStates = check.SatisfyingStateIds.Count, FixedPointIterations = check.FixedPointIterations, TraceStateIds = check.TraceStateIds.Take(4096).ToList(), TraceTransitionIds = check.TraceTransitionIds.Take(4096).ToList() }; run.EvidenceNodeIds = EvidenceForTrace(model, run).Take(MaxEvidenceAnchors * 2).ToList(); Store.Runs.Insert(0, run); Store.FormulaHistory.RemoveAll(f => String.Equals(f, property.Formula, StringComparison.OrdinalIgnoreCase)); Store.FormulaHistory.Insert(0, property.Formula); TrimStore(); Save(ctx); AppendLedger(ctx, "PROPERTY_CHECKED_" + run.Outcome, property.Id, property.Name + " · " + run.NormalizedFormula, run.ModelFingerprint, run.CertificateHash); if (open) OpenRun(owner, ctx, index, run); return run;
        }

