        {
            Window w = W(owner, "YOMI · VERIFICATION CERTIFICATE VAULT", 1200, 790); DockPanel root = Shell("COUNTEREXAMPLE / CERTIFICATE VAULT", "Each run is bound to an exact model fingerprint, normalized formula, satisfying-state cardinality, minimized trace and SHA-256 certificate."); ListBox list = List(); list.ItemsSource = Store.Runs.OrderByDescending(r => r.CheckedUtc).ToList(); list.MouseDoubleClick += delegate { VerificationRun run = list.SelectedItem as VerificationRun; if (run != null) OpenRun(w, ctx, index, run); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void OpenRun(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationRun run)
        {
            VerificationModel model = Model(run.ModelId); Window w = W(owner, "YOMI · " + run.Outcome + " · " + run.PropertyName, 1220, 820); DockPanel root = Shell(run.Outcome + " · " + run.PropertyName, (run.NormalizedFormula ?? run.Formula) + "\r\nModel fingerprint " + run.ModelFingerprint + " · certificate " + run.CertificateHash + " · fixed-point iterations " + run.FixedPointIterations); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("MODEL", delegate { if (model != null) OpenModel(w, ctx, index, model); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, run.PropertyName, run, StorePath(ctx), "$runs:" + run.Id, "VERIFICATION REACTOR › CERTIFICATE"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox trace = List(); trace.ItemsSource = TraceRows(model, run); trace.MouseDoubleClick += delegate { VerificationTraceRow row = trace.SelectedItem as VerificationTraceRow; if (row == null || model == null) return; if (row.State != null) OpenState(w, ctx, index, model, row.State); else if (row.Transition != null) OpenTransition(w, ctx, index, model, row.Transition); }; DockPanel.SetDock(trace, Dock.Top); trace.MaxHeight = 380; root.Children.Add(trace); ListBox evidence = EvidenceList(w, ctx, index, run.EvidenceNodeIds); root.Children.Add(evidence); w.Content = root; w.Show();
        }

        private static void OpenTopology(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            VerificationTopology topology = VerificationKernel.AnalyzeTopology(model, new VerificationKernelLimits()); Window w = W(owner, "YOMI · STATE-SPACE OBSERVATORY · " + model.Name, 1200, 800); DockPanel root = Shell("STATE-SPACE TOPOLOGY · " + model.Name, "Reachable " + topology.ReachableStates + "/" + topology.TotalStates + " · transitions " + topology.TotalTransitions + " · deadlocks " + topology.Deadlocks + " · nondeterministic " + topology.NondeterministicStates + " · diameter ≤ " + topology.Diameter + " · mean branching " + topology.MeanBranching.ToString("0.000", CultureInfo.InvariantCulture) + " · branching entropy " + topology.BranchingEntropy.ToString("0.000", CultureInfo.InvariantCulture)); Grid grid = new Grid(); grid.ColumnDefinitions.Add(new ColumnDefinition()); grid.ColumnDefinitions.Add(new ColumnDefinition()); ListBox components = List(); components.ItemsSource = topology.Components; components.MouseDoubleClick += delegate { VerificationScc component = components.SelectedItem as VerificationScc; if (component != null) OpenComponent(w, ctx, index, model, component); }; StringBuilder s = new StringBuilder(); s.AppendLine("UNREACHABLE STATES"); foreach (string id in topology.UnreachableStateIds) { VerificationState state = State(model, id); s.AppendLine("  " + (state == null ? id : state.Name + " · " + state.Id)); } s.AppendLine(); s.AppendLine("DEADLOCK STATES"); foreach (string id in topology.DeadlockStateIds) { VerificationState state = State(model, id); s.AppendLine("  " + (state == null ? id : state.Name + " · " + state.Id)); } TextBox findings = ReadOnly(s.ToString()); Grid.SetColumn(components, 0); Grid.SetColumn(findings, 1); grid.Children.Add(components); grid.Children.Add(findings); root.Children.Add(grid); w.Content = root; w.Show();
        }

        private static void OpenComponents(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
