        private static void OpenInvariantSynthesis(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            List<VerificationInvariantCandidate> candidates = VerificationKernel.SynthesizeInvariants(model, new VerificationKernelLimits()); Window w = W(owner, "YOMI · INVARIANT SYNTHESIS · " + model.Name, 1220, 810); DockPanel root = Shell("MACHINE-SYNTHESIZED INVARIANT CANDIDATES", "Candidates are derived from the current reachable state set. They are structural conjectures, not requirements, until promoted and independently checked."); ListBox list = List(); list.ItemsSource = candidates; list.MouseDoubleClick += delegate { VerificationInvariantCandidate candidate = list.SelectedItem as VerificationInvariantCandidate; if (candidate != null) OpenInvariantCandidate(w, ctx, index, model, candidate); }; root.Children.Add(list); w.Content = root; w.Show();
