        private static void RunMutationCampaign(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            List<VerificationProperty> properties = Store.Properties.Where(p => Active(p.Status) && String.Equals(p.ModelId, model.Id, StringComparison.OrdinalIgnoreCase)).Take(256).ToList(); if (properties.Count == 0) { MessageBox.Show(owner, "This model has no active property arsenal. Author properties before measuring mutation adequacy.", "YOMI · Mutation Lab"); return; } Dictionary<string, string> baseline = properties.ToDictionary(p => p.Id, p => VerificationKernel.Check(model, p.Formula, new VerificationKernelLimits()).Passed ? "PASS" : "FAIL", StringComparer.OrdinalIgnoreCase); List<VerificationMutationResult> results = new List<VerificationMutationResult>(); foreach (VerificationTransition transition in model.Transitions.Where(t => !String.Equals(t.Status, "DISABLED", StringComparison.OrdinalIgnoreCase)).Take(192)) { VerificationModel mutant = CloneModel(model); mutant.Transitions.RemoveAll(t => String.Equals(t.Id, transition.Id, StringComparison.OrdinalIgnoreCase)); results.Add(EvaluateMutant(mutant, properties, baseline, "DELETE_TRANSITION", transition.Id, transition.Name)); } foreach (VerificationState state in model.States.Take(128)) foreach (string label in state.Labels.Take(4)) { VerificationModel mutant = CloneModel(model); VerificationState changed = State(mutant, state.Id); changed.Labels.RemoveAll(x => String.Equals(x, label, StringComparison.OrdinalIgnoreCase)); results.Add(EvaluateMutant(mutant, properties, baseline, "DROP_LABEL", state.Id, state.Name + " · " + label)); if (results.Count >= MaxMutationResults) break; } results = results.Take(MaxMutationResults).ToList(); VerificationMutationCampaign campaign = new VerificationMutationCampaign { Id = Id("mutation"), ModelId = model.Id, CreatedUtc = Now(), ModelFingerprint = VerificationKernel.Fingerprint(model), Mutants = results.Count, Killed = results.Count(r => r.ChangedProperties > 0), Survived = results.Count(r => r.ChangedProperties == 0), Results = results }; campaign.MutationScore = campaign.Mutants == 0 ? 0 : campaign.Killed / (double)campaign.Mutants; Store.MutationCampaigns.Insert(0, campaign); TrimStore(); Save(ctx); AppendLedger(ctx, "MUTATION_CAMPAIGN", campaign.Id, campaign.Killed + " killed / " + campaign.Survived + " survived", campaign.ModelFingerprint, HashText(Json.Serialize(campaign.Results))); OpenMutationCampaign(owner, ctx, index, model, campaign);
        }

        private static VerificationMutationResult EvaluateMutant(VerificationModel mutant, List<VerificationProperty> properties, Dictionary<string, string> baseline, string kind, string subjectId, string description)
        {
            VerificationMutationResult result = new VerificationMutationResult { MutationId = Id("mutant"), Kind = kind, SubjectId = subjectId, Description = description }; foreach (VerificationProperty property in properties) { VerificationCheckResult check = VerificationKernel.Check(mutant, property.Formula, new VerificationKernelLimits()); string outcome = check.Parsed && check.Passed ? "PASS" : "FAIL"; if (!String.Equals(outcome, baseline[property.Id], StringComparison.OrdinalIgnoreCase)) result.ChangedPropertyIds.Add(property.Id); } result.ChangedProperties = result.ChangedPropertyIds.Count; result.Outcome = result.ChangedProperties > 0 ? "KILLED" : "SURVIVED"; return result;
        }

        private static void OpenMutationCampaign(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model, VerificationMutationCampaign campaign)
        {
            Window w = W(owner, "YOMI · MUTATION ADEQUACY · " + model.Name, 1200, 800); DockPanel root = Shell("MUTATION SCORE " + campaign.MutationScore.ToString("P1", CultureInfo.InvariantCulture), campaign.Killed + " killed · " + campaign.Survived + " survived · " + campaign.Mutants + " bounded semantic mutations · survivors identify property blind spots, not necessarily defects"); ListBox list = List(); list.ItemsSource = campaign.Results.OrderBy(r => r.Outcome == "SURVIVED" ? 0 : 1).ThenBy(r => r.Kind).ThenBy(r => r.Description).ToList(); list.MouseDoubleClick += delegate { VerificationMutationResult result = list.SelectedItem as VerificationMutationResult; if (result != null) DeepSystems.OpenExternalValue(w, ctx, result.Kind + " · " + result.Description, result, "VERIFICATION REACTOR › MUTATION"); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static VerificationModel CreateAnchoredModel(DeepSystemsContext ctx, WorldNode node)
        {
            VerificationModel model = new VerificationModel { Id = Id("model"), ParentModelId = "world-node:" + node.Id, SourceFingerprint = node.Fingerprint, Name = "World protocol · " + Short(node.Label ?? node.Kind, 160), Description = "Evidence-anchored seed model created from an exact World Passport. Extend it with states and transitions before making broad claims.", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1, EvidenceNodeIds = new List<string> { node.Id } }; VerificationState state = new VerificationState { Id = Id("state"), Name = "observed_object", Description = node.Summary, Status = "ACTIVE", Labels = new List<string> { "world:anchored", "kind:" + NormalizeSymbol(node.Kind) }, EvidenceNodeIds = new List<string> { node.Id } }; state.Properties["world_id"] = node.Id; state.Properties["fingerprint"] = node.Fingerprint ?? ""; model.States.Add(state); model.InitialStateIds.Add(state.Id); model.Transitions.Add(new VerificationTransition { Id = Id("transition"), FromStateId = state.Id, ToStateId = state.Id, Name = "stutter", Kind = "INTERNAL", Guard = "observation remains in the bounded seed abstraction", Action = "none", EvidenceNodeIds = new List<string> { node.Id } }); Store.Models.Insert(0, model); Store.Properties.Insert(0, new VerificationProperty { Id = Id("property"), ModelId = model.Id, Name = "World anchor retained", Formula = "AG world:anchored", Kind = "SAFETY", Severity = "REQUIRED", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now() }); TrimStore(); Save(ctx); AppendLedger(ctx, "WORLD_MODEL_CREATED", model.Id, model.Name, VerificationKernel.Fingerprint(model), node.Fingerprint); return model;
        }

        private static VerificationModel CreateTheoryObservationModel(DeepSystemsContext ctx, LogicTheory theory, Dictionary<string, string> truth, string sourceFingerprint)
        {
            truth = truth ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); VerificationModel model = new VerificationModel { Id = Id("model"), ParentModelId = "logic-theory:" + theory.Id, SourceFingerprint = sourceFingerprint, Name = "Theory automaton · " + Short(theory.Name, 160), Description = "A verification projection of frozen Epistemic Logic theory questions. Each question is an observation state labeled with its four-valued result.", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1 }; foreach (KeyValuePair<string, string> row in truth.OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase).Take(MaxStatesPerModel)) { VerificationState state = new VerificationState { Id = Id("state"), Name = Short(row.Key, 180), Description = "Frozen theory question observation", Status = "ACTIVE", Labels = new List<string> { "truth:" + row.Value, "theory:observation" } }; state.Properties["query"] = row.Key; state.Properties["truth"] = row.Value; model.States.Add(state); model.InitialStateIds.Add(state.Id); model.Transitions.Add(new VerificationTransition { Id = Id("transition"), FromStateId = state.Id, ToStateId = state.Id, Name = "observe", Kind = "INTERNAL" }); } if (model.States.Count == 0) { VerificationState empty = new VerificationState { Id = Id("state"), Name = "no_questions", Status = "ACTIVE", Labels = new List<string> { "truth:NEITHER", "theory:empty" } }; model.States.Add(empty); model.InitialStateIds.Add(empty.Id); } Store.Models.Insert(0, model); Store.Properties.Insert(0, new VerificationProperty { Id = Id("property"), ModelId = model.Id, Name = "No contradictory observation", Formula = "AG !truth:BOTH", Kind = "SAFETY", Severity = "DESIRED", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now() }); TrimStore(); Save(ctx); AppendLedger(ctx, "THEORY_MODEL_CREATED", model.Id, theory.Id + " · " + truth.Count + " questions", VerificationKernel.Fingerprint(model), sourceFingerprint); return model;
        }

        private static VerificationModel CreateResolutionLifecycleModel(DeepSystemsContext ctx, CivilResolution resolution, string sourceFingerprint)
        {
            List<string> evidence = (resolution.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidenceAnchors).ToList(); VerificationModel model = new VerificationModel { Id = Id("model"), ParentModelId = "civil-resolution:" + resolution.Id, SourceFingerprint = sourceFingerprint, Name = "Resolution lifecycle · " + Short(resolution.Title, 140), Description = "Finite lifecycle abstraction of one Civilization resolution. Organizational transitions remain distinct from proposition truth.", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1, EvidenceNodeIds = evidence.ToList() }; Dictionary<string, VerificationState> states = new Dictionary<string, VerificationState>(StringComparer.OrdinalIgnoreCase); foreach (string status in new[] { "DRAFT", "DELIBERATING", "ADOPTED", "RETIRED" }) { VerificationState state = new VerificationState { Id = Id("state"), Name = status.ToLowerInvariant(), Description = "Resolution status " + status, Status = "ACTIVE", Labels = new List<string> { "status:" + status.ToLowerInvariant(), status == "ADOPTED" || status == "RETIRED" ? "terminal" : "open" }, EvidenceNodeIds = evidence.ToList() }; state.Properties["resolution_id"] = resolution.Id; state.Properties["epistemic_class"] = resolution.EpistemicClass ?? "QUESTION"; states[status] = state; model.States.Add(state); } VerificationState initial; if (!states.TryGetValue(resolution.Status ?? "DRAFT", out initial)) initial = states["DRAFT"]; model.InitialStateIds.Add(initial.Id); AddLifecycleTransition(model, states["DRAFT"], states["DELIBERATING"], "begin_deliberation"); AddLifecycleTransition(model, states["DRAFT"], states["ADOPTED"], "adopt_directly"); AddLifecycleTransition(model, states["DRAFT"], states["RETIRED"], "retire_draft"); AddLifecycleTransition(model, states["DELIBERATING"], states["ADOPTED"], "adopt"); AddLifecycleTransition(model, states["DELIBERATING"], states["RETIRED"], "retire"); AddLifecycleTransition(model, states["ADOPTED"], states["ADOPTED"], "terminal_stutter"); AddLifecycleTransition(model, states["RETIRED"], states["RETIRED"], "terminal_stutter"); Store.Models.Insert(0, model); Store.Properties.Insert(0, new VerificationProperty { Id = Id("property"), ModelId = model.Id, Name = "Exclusive terminal status", Formula = "AG !(status:adopted & status:retired)", Kind = "SAFETY", Severity = "CRITICAL", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now() }); Store.Properties.Insert(0, new VerificationProperty { Id = Id("property"), ModelId = model.Id, Name = "Eventually terminal", Formula = "AF terminal", Kind = "LIVENESS", Severity = "DESIRED", Status = "ACTIVE", CreatedUtc = Now(), UpdatedUtc = Now() }); TrimStore(); Save(ctx); AppendLedger(ctx, "RESOLUTION_MODEL_CREATED", model.Id, resolution.Id + " · current " + resolution.Status, VerificationKernel.Fingerprint(model), sourceFingerprint); return model;
        }

        private static void AddLifecycleTransition(VerificationModel model, VerificationState from, VerificationState to, string name) { model.Transitions.Add(new VerificationTransition { Id = Id("transition"), FromStateId = from.Id, ToStateId = to.Id, Name = name, Kind = "ORGANIZATIONAL", Guard = "explicit council action", Action = to.Name }); }

        private static void ForkModel(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel source)
        {
            string name = Prompt(owner, "FORK MODEL", "Counterfactual model name", source.Name + " · branch"); if (String.IsNullOrWhiteSpace(name)) return; VerificationModel fork = CloneModelWithNewIdentities(source); fork.ParentModelId = source.Id; fork.SourceFingerprint = VerificationKernel.Fingerprint(source); fork.Id = Id("model"); fork.Name = Short(name, 240); fork.Status = "ACTIVE"; fork.CreatedUtc = Now(); fork.UpdatedUtc = Now(); fork.Revision = 1; Store.Models.Insert(0, fork); foreach (VerificationProperty property in Store.Properties.Where(p => String.Equals(p.ModelId, source.Id, StringComparison.OrdinalIgnoreCase)).Take(128)) Store.Properties.Insert(0, new VerificationProperty { Id = Id("property"), ModelId = fork.Id, Name = property.Name, Formula = property.Formula, Kind = property.Kind, Severity = property.Severity, Status = property.Status, CreatedUtc = Now(), UpdatedUtc = Now() }); TrimStore(); Save(ctx); AppendLedger(ctx, "MODEL_FORKED", fork.Id, "parent " + source.Id, VerificationKernel.Fingerprint(fork), ""); OpenModel(owner, ctx, index, fork);
        }

        private static VerificationModel CloneModel(VerificationModel source)
        {
            VerificationModel clone = new VerificationModel { Id = source.Id, ParentModelId = source.ParentModelId, SourceFingerprint = source.SourceFingerprint, Name = source.Name, Description = source.Description, Status = source.Status, CreatedUtc = source.CreatedUtc, UpdatedUtc = source.UpdatedUtc, Revision = source.Revision, InitialStateIds = source.InitialStateIds.ToList(), EvidenceNodeIds = source.EvidenceNodeIds.ToList() }; foreach (VerificationState s in source.States) clone.States.Add(new VerificationState { Id = s.Id, Name = s.Name, Description = s.Description, Status = s.Status, Labels = s.Labels.ToList(), Properties = new Dictionary<string, string>(s.Properties, StringComparer.OrdinalIgnoreCase), EvidenceNodeIds = s.EvidenceNodeIds.ToList() }); foreach (VerificationTransition t in source.Transitions) clone.Transitions.Add(new VerificationTransition { Id = t.Id, FromStateId = t.FromStateId, ToStateId = t.ToStateId, Name = t.Name, Kind = t.Kind, Status = t.Status, Guard = t.Guard, Action = t.Action, FairnessGroup = t.FairnessGroup, EvidenceNodeIds = t.EvidenceNodeIds.ToList() }); return clone;
        }

        private static VerificationModel CloneModelWithNewIdentities(VerificationModel source)
        {
            VerificationModel clone = CloneModel(source); Dictionary<string, string> map = clone.States.ToDictionary(s => s.Id, s => Id("state"), StringComparer.OrdinalIgnoreCase); foreach (VerificationState state in clone.States) state.Id = map[state.Id]; clone.InitialStateIds = clone.InitialStateIds.Where(map.ContainsKey).Select(id => map[id]).ToList(); foreach (VerificationTransition transition in clone.Transitions) { transition.Id = Id("transition"); transition.FromStateId = map[transition.FromStateId]; transition.ToStateId = map[transition.ToStateId]; } return clone;
        }

        private static void OpenAudit(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            List<VerificationAuditFinding> findings = BuildAudit(ctx, index); int failures = findings.Count(f => f.Severity == "FAIL"), warnings = findings.Count(f => f.Severity == "WARN"); Window w = W(owner, "YOMI · REACTOR AUDIT CHAMBER", 1220, 820); DockPanel root = Shell("READ-ONLY FORMAL-METHODS AUDIT", failures + " failures · " + warnings + " warnings · " + findings.Count(f => f.Severity == "INFO") + " information findings · audit evaluation never grants repair or runtime authority"); ListBox list = List(); list.ItemsSource = findings.OrderBy(f => f.Severity == "FAIL" ? 0 : f.Severity == "WARN" ? 1 : 2).ThenBy(f => f.Code).ThenBy(f => f.SubjectId).ToList(); list.MouseDoubleClick += delegate { VerificationAuditFinding finding = list.SelectedItem as VerificationAuditFinding; if (finding == null) return; if (!String.IsNullOrWhiteSpace(finding.NodeId) && index.Nodes.ContainsKey(finding.NodeId)) WorldKernel.ExternalOpenDossier(w, ctx, index, finding.NodeId); else DeepSystems.OpenExternalValue(w, ctx, finding.Code + " · " + finding.SubjectId, finding, "VERIFICATION REACTOR › AUDIT"); }; root.Children.Add(list); w.Content = root; w.Show(); AppendLedger(ctx, "REACTOR_AUDIT", "store", failures + " failures · " + warnings + " warnings", HashText(String.Join("|", findings.Select(f => f.Severity + ":" + f.Code + ":" + f.SubjectId).ToArray())), "");
        }

        private static List<VerificationAuditFinding> BuildAudit(DeepSystemsContext ctx, WorldIndex index)
        {
            List<VerificationAuditFinding> rows = new List<VerificationAuditFinding>(); List<string> globalIds = new List<string>(); globalIds.AddRange(Store.Models.Select(x => x.Id)); globalIds.AddRange(Store.Properties.Select(x => x.Id)); globalIds.AddRange(Store.Runs.Select(x => x.Id)); globalIds.AddRange(Store.Invariants.Select(x => x.Id)); globalIds.AddRange(Store.MutationCampaigns.Select(x => x.Id)); globalIds.AddRange(Store.Models.SelectMany(m => m.States.Select(x => x.Id))); globalIds.AddRange(Store.Models.SelectMany(m => m.Transitions.Select(x => x.Id))); foreach (IGrouping<string, string> group in globalIds.Where(x => !String.IsNullOrWhiteSpace(x)).GroupBy(x => x, StringComparer.OrdinalIgnoreCase).Where(g => g.Count() > 1)) Finding(rows, "FAIL", "DUPLICATE_ID", group.Key, group.Count() + " objects share this identity", null);
            foreach (VerificationModel model in Store.Models) { HashSet<string> stateIds = new HashSet<string>(model.States.Select(s => s.Id), StringComparer.OrdinalIgnoreCase); if (!String.IsNullOrWhiteSpace(model.ParentModelId) && String.IsNullOrWhiteSpace(model.SourceFingerprint)) Finding(rows, "WARN", "PROJECTION_WITHOUT_SOURCE_FINGERPRINT", model.Id, model.ParentModelId, null); if (model.States.Count == 0) Finding(rows, "FAIL", "MODEL_WITHOUT_STATES", model.Id, model.Name, null); if (model.InitialStateIds.Count == 0) Finding(rows, "FAIL", "MODEL_WITHOUT_INITIAL", model.Id, model.Name, null); foreach (string initial in model.InitialStateIds.Where(id => !stateIds.Contains(id))) Finding(rows, "FAIL", "ORPHAN_INITIAL_STATE", model.Id, initial, null); foreach (VerificationState state in model.States) { if (String.IsNullOrWhiteSpace(state.Name)) Finding(rows, "WARN", "STATE_WITHOUT_NAME", state.Id, model.Id, null); if (state.Labels.Any(String.IsNullOrWhiteSpace)) Finding(rows, "WARN", "EMPTY_STATE_LABEL", state.Id, model.Id, null); foreach (string nodeId in state.EvidenceNodeIds.Where(id => !index.Nodes.ContainsKey(id))) Finding(rows, "INFO", "STATE_EVIDENCE_ABSENT", state.Id, nodeId, nodeId); AuditBound(rows, "STATE_LABELS:" + state.Id, state.Labels.Count, MaxLabelsPerState); AuditBound(rows, "STATE_PROPERTIES:" + state.Id, state.Properties.Count, MaxPropertiesPerState); } foreach (VerificationTransition transition in model.Transitions) { if (!stateIds.Contains(transition.FromStateId)) Finding(rows, "FAIL", "ORPHAN_TRANSITION_ORIGIN", transition.Id, transition.FromStateId, null); if (!stateIds.Contains(transition.ToStateId)) Finding(rows, "FAIL", "ORPHAN_TRANSITION_DESTINATION", transition.Id, transition.ToStateId, null); if (String.IsNullOrWhiteSpace(transition.Name)) Finding(rows, "WARN", "TRANSITION_WITHOUT_NAME", transition.Id, model.Id, null); foreach (string nodeId in transition.EvidenceNodeIds.Where(id => !index.Nodes.ContainsKey(id))) Finding(rows, "INFO", "TRANSITION_EVIDENCE_ABSENT", transition.Id, nodeId, nodeId); } foreach (string nodeId in model.EvidenceNodeIds.Where(id => !index.Nodes.ContainsKey(id))) Finding(rows, "INFO", "MODEL_EVIDENCE_ABSENT", model.Id, nodeId, nodeId); AuditBound(rows, "MODEL_STATES:" + model.Id, model.States.Count, MaxStatesPerModel); AuditBound(rows, "MODEL_TRANSITIONS:" + model.Id, model.Transitions.Count, MaxTransitionsPerModel); }
            foreach (VerificationProperty property in Store.Properties) { VerificationModel model = Model(property.ModelId); if (model == null) Finding(rows, "FAIL", "ORPHAN_PROPERTY_MODEL", property.Id, property.ModelId, null); TemporalFormula parsed; string error; if (!TemporalFormulaParser.TryParse(property.Formula, 96, out parsed, out error)) Finding(rows, "FAIL", "PROPERTY_PARSE_ERROR", property.Id, error, null); }
            foreach (VerificationRun run in Store.Runs) { VerificationModel model = Model(run.ModelId); if (model == null) { Finding(rows, "WARN", "ORPHAN_RUN_MODEL", run.Id, run.ModelId, null); continue; } string current = VerificationKernel.Fingerprint(model); if (!String.Equals(current, run.ModelFingerprint, StringComparison.OrdinalIgnoreCase)) Finding(rows, "INFO", "HISTORICAL_MODEL_DIVERGENCE", run.Id, "Run " + Short(run.ModelFingerprint, 16) + " / current " + Short(current, 16), null); else { VerificationCheckResult repeat = VerificationKernel.Check(model, run.Formula, new VerificationKernelLimits()); if (!String.Equals(repeat.CertificateHash ?? "", run.CertificateHash ?? "", StringComparison.OrdinalIgnoreCase)) Finding(rows, "FAIL", "CERTIFICATE_DIVERGENCE", run.Id, "Stored certificate does not match deterministic reevaluation", null); } foreach (string id in run.TraceStateIds.Where(id => !model.States.Any(s => String.Equals(s.Id, id, StringComparison.OrdinalIgnoreCase)))) Finding(rows, "INFO", "HISTORICAL_TRACE_STATE_ABSENT", run.Id, id, null); }
            foreach (VerificationInvariantRecord invariant in Store.Invariants) { if (Model(invariant.ModelId) == null) Finding(rows, "WARN", "ORPHAN_INVARIANT_MODEL", invariant.Id, invariant.ModelId, null); TemporalFormula parsed; string error; if (!TemporalFormulaParser.TryParse(invariant.Formula, 96, out parsed, out error)) Finding(rows, "FAIL", "INVARIANT_PARSE_ERROR", invariant.Id, error, null); }
            foreach (VerificationMutationCampaign campaign in Store.MutationCampaigns) { if (Model(campaign.ModelId) == null) Finding(rows, "WARN", "ORPHAN_MUTATION_MODEL", campaign.Id, campaign.ModelId, null); if (campaign.Mutants != campaign.Results.Count || campaign.Killed + campaign.Survived != campaign.Mutants) Finding(rows, "FAIL", "MUTATION_CARDINALITY", campaign.Id, campaign.Killed + "+" + campaign.Survived + " != " + campaign.Mutants, null); }
            AuditBound(rows, "MODELS", Store.Models.Count, MaxModels); AuditBound(rows, "PROPERTIES", Store.Properties.Count, MaxProperties); AuditBound(rows, "RUNS", Store.Runs.Count, MaxRuns); AuditBound(rows, "INVARIANTS", Store.Invariants.Count, MaxInvariants); AuditBound(rows, "MUTATION_CAMPAIGNS", Store.MutationCampaigns.Count, MaxMutationCampaigns); string ledger = VerifyLedger(ReadLedger(ctx, 8192)); if (ledger == "EMPTY LEDGER" || ledger.StartsWith("CHAIN VERIFIED", StringComparison.OrdinalIgnoreCase)) Finding(rows, "INFO", "LEDGER_STATUS", "ledger", ledger, null); else Finding(rows, "FAIL", "LEDGER_INTEGRITY", "ledger", ledger, null); if (rows.Count == 1 && rows[0].Code == "LEDGER_STATUS") Finding(rows, "INFO", "STRUCTURE_CLEAN", "store", "No bounded structural findings", null); return rows;
        }

        private static void Finding(List<VerificationAuditFinding> rows, string severity, string code, string subject, string detail, string nodeId) { rows.Add(new VerificationAuditFinding { Severity = severity, Code = code, SubjectId = subject, Detail = detail, NodeId = nodeId }); }
        private static void AuditBound(List<VerificationAuditFinding> rows, string subject, int count, int bound) { if (count > bound) Finding(rows, "FAIL", "BOUND_EXCEEDED", subject, count + " > " + bound, null); }

        private static void OpenLedger(Window owner, DeepSystemsContext ctx)
        {
            List<VerificationLedgerRecord> records = ReadLedger(ctx, 8192); Window w = W(owner, "YOMI · VERIFICATION LEDGER", 1180, 780); DockPanel root = Shell("APPEND-ONLY VERIFICATION LEDGER", VerifyLedger(records) + " · mutations bind store commit, model fingerprint, certificate and prior record hash"); WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("VERIFY CHAIN", delegate { MessageBox.Show(w, VerifyLedger(ReadLedger(ctx, 8192)), "YOMI · Verification Ledger"); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, "Verification Ledger", records, LedgerPath(ctx), "$ledger", "VERIFICATION REACTOR › LEDGER"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = records.OrderByDescending(r => r.Sequence).ToList(); list.MouseDoubleClick += delegate { VerificationLedgerRecord record = list.SelectedItem as VerificationLedgerRecord; if (record != null) DeepSystems.OpenExternalValue(w, ctx, "VERIFICATION LEDGER " + record.Sequence, record, "VERIFICATION REACTOR › LEDGER"); }; root.Children.Add(list); w.Content = root; w.Show();
