        private static void Load(DeepSystemsContext ctx)
        {
            lock (Gate) { if (Store != null && String.Equals(LoadedRoot, ctx.DataRoot, StringComparison.OrdinalIgnoreCase)) return; LoadedRoot = ctx.DataRoot; Store = new VerificationReactorStore(); string path = StorePath(ctx); try { if (File.Exists(path)) { VerificationReactorStore loaded = Json.Deserialize<VerificationReactorStore>(File.ReadAllText(path, Encoding.UTF8)); if (loaded == null || loaded.Schema > 1) throw new InvalidDataException("Unsupported Verification Reactor schema."); Store = loaded; } } catch { PreserveCorrupt(path); Store = LoadPrevious(path) ?? new VerificationReactorStore(); } NormalizeStore(); }
        }

        private static VerificationReactorStore LoadPrevious(string path) { try { string previous = path + ".previous"; if (!File.Exists(previous)) return null; VerificationReactorStore loaded = Json.Deserialize<VerificationReactorStore>(File.ReadAllText(previous, Encoding.UTF8)); return loaded != null && loaded.Schema <= 1 ? loaded : null; } catch { return null; } }

        private static void NormalizeStore()
        {
            if (Store == null) Store = new VerificationReactorStore(); Store.Schema = 1; if (Store.Models == null) Store.Models = new List<VerificationModel>(); if (Store.Properties == null) Store.Properties = new List<VerificationProperty>(); if (Store.Runs == null) Store.Runs = new List<VerificationRun>(); if (Store.Invariants == null) Store.Invariants = new List<VerificationInvariantRecord>(); if (Store.MutationCampaigns == null) Store.MutationCampaigns = new List<VerificationMutationCampaign>(); if (Store.FormulaHistory == null) Store.FormulaHistory = new List<string>(); foreach (VerificationModel model in Store.Models) { if (model.InitialStateIds == null) model.InitialStateIds = new List<string>(); if (model.States == null) model.States = new List<VerificationState>(); if (model.Transitions == null) model.Transitions = new List<VerificationTransition>(); if (model.EvidenceNodeIds == null) model.EvidenceNodeIds = new List<string>(); if (String.IsNullOrWhiteSpace(model.Status)) model.Status = "ACTIVE"; if (model.Revision < 1) model.Revision = 1; foreach (VerificationState state in model.States) { if (state.Labels == null) state.Labels = new List<string>(); if (state.Properties == null) state.Properties = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); if (state.EvidenceNodeIds == null) state.EvidenceNodeIds = new List<string>(); if (String.IsNullOrWhiteSpace(state.Status)) state.Status = "ACTIVE"; } foreach (VerificationTransition transition in model.Transitions) { if (transition.EvidenceNodeIds == null) transition.EvidenceNodeIds = new List<string>(); if (String.IsNullOrWhiteSpace(transition.Kind)) transition.Kind = "STEP"; if (String.IsNullOrWhiteSpace(transition.Status)) transition.Status = "ACTIVE"; } } foreach (VerificationProperty property in Store.Properties) if (String.IsNullOrWhiteSpace(property.Status)) property.Status = "ACTIVE"; foreach (VerificationRun run in Store.Runs) { if (run.TraceStateIds == null) run.TraceStateIds = new List<string>(); if (run.TraceTransitionIds == null) run.TraceTransitionIds = new List<string>(); if (run.EvidenceNodeIds == null) run.EvidenceNodeIds = new List<string>(); } foreach (VerificationMutationCampaign campaign in Store.MutationCampaigns) { if (campaign.Results == null) campaign.Results = new List<VerificationMutationResult>(); foreach (VerificationMutationResult result in campaign.Results) if (result.ChangedPropertyIds == null) result.ChangedPropertyIds = new List<string>(); } TrimStore();
        }

        private static void TrimStore()
        {
            Store.Models = Store.Models.OrderByDescending(m => m.UpdatedUtc ?? m.CreatedUtc).Take(MaxModels).ToList(); Store.Properties = Store.Properties.OrderByDescending(p => p.UpdatedUtc ?? p.CreatedUtc).Take(MaxProperties).ToList(); Store.Runs = Store.Runs.OrderByDescending(r => r.CheckedUtc).Take(MaxRuns).ToList(); Store.Invariants = Store.Invariants.OrderByDescending(i => i.UpdatedUtc ?? i.CreatedUtc).Take(MaxInvariants).ToList(); Store.MutationCampaigns = Store.MutationCampaigns.OrderByDescending(c => c.CreatedUtc).Take(MaxMutationCampaigns).ToList(); Store.FormulaHistory = Store.FormulaHistory.Where(x => !String.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxFormulaHistory).ToList(); foreach (VerificationModel model in Store.Models) { model.States = model.States.Take(MaxStatesPerModel).ToList(); HashSet<string> ids = new HashSet<string>(model.States.Select(s => s.Id), StringComparer.OrdinalIgnoreCase); model.InitialStateIds = model.InitialStateIds.Where(ids.Contains).Distinct(StringComparer.OrdinalIgnoreCase).Take(64).ToList(); model.Transitions = model.Transitions.Where(t => ids.Contains(t.FromStateId) && ids.Contains(t.ToStateId)).Take(MaxTransitionsPerModel).ToList(); model.EvidenceNodeIds = model.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); foreach (VerificationState state in model.States) { state.Labels = state.Labels.Where(x => !String.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxLabelsPerState).ToList(); state.Properties = state.Properties.Take(MaxPropertiesPerState).ToDictionary(x => x.Key, x => x.Value, StringComparer.OrdinalIgnoreCase); state.EvidenceNodeIds = state.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); } foreach (VerificationTransition transition in model.Transitions) transition.EvidenceNodeIds = transition.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors).ToList(); } foreach (VerificationRun run in Store.Runs) { run.TraceStateIds = run.TraceStateIds.Take(4096).ToList(); run.TraceTransitionIds = run.TraceTransitionIds.Take(4096).ToList(); run.EvidenceNodeIds = run.EvidenceNodeIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxEvidenceAnchors * 2).ToList(); } foreach (VerificationMutationCampaign campaign in Store.MutationCampaigns) campaign.Results = campaign.Results.Take(MaxMutationResults).ToList();
        }

        private static void Save(DeepSystemsContext ctx) { lock (Gate) { NormalizeStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("verification-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }

        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string modelFingerprint, string certificate)
        {
            lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<VerificationLedgerRecord> prior = ReadLedger(ctx, 8192); VerificationLedgerRecord last = prior.OrderByDescending(r => r.Sequence).FirstOrDefault(); VerificationLedgerRecord record = new VerificationLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(modelFingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; record.EntryHash = LedgerHash(record); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(record) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { }
        }

        private static List<VerificationLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<VerificationLedgerRecord> rows = new List<VerificationLedgerRecord>(); string path = LedgerPath(ctx); if (!File.Exists(path)) return rows; try { foreach (string line in TakeLastLocal(File.ReadLines(path).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { VerificationLedgerRecord record = Json.Deserialize<VerificationLedgerRecord>(line); if (record != null) rows.Add(record); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<VerificationLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(r => r.Sequence).ToList(); string previous = rows[0].PrevHash; long expected = rows[0].Sequence; foreach (VerificationLedgerRecord record in rows) { if (record.Sequence != expected) return "CHAIN GAP @ " + expected; if (!String.Equals(record.PrevHash ?? "", previous ?? "", StringComparison.OrdinalIgnoreCase)) return "PREV HASH MISMATCH @ " + record.Sequence; if (!String.Equals(record.EntryHash ?? "", LedgerHash(record), StringComparison.OrdinalIgnoreCase)) return "ENTRY HASH MISMATCH @ " + record.Sequence; previous = record.EntryHash; expected++; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(VerificationLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-axiomatic-verification.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-axiomatic-verification-ledger.jsonl"); }

        private static VerificationModel Model(string id) { return Store.Models.FirstOrDefault(m => String.Equals(m.Id, id, StringComparison.OrdinalIgnoreCase)); }
        private static VerificationState State(VerificationModel model, string id) { return model == null ? null : model.States.FirstOrDefault(s => String.Equals(s.Id, id, StringComparison.OrdinalIgnoreCase)); }
        private static VerificationTransition Transition(VerificationModel model, string id) { return model == null ? null : model.Transitions.FirstOrDefault(t => String.Equals(t.Id, id, StringComparison.OrdinalIgnoreCase)); }
        private static VerificationModel ChooseModel(Window owner) { return ChooseObject(owner, "SELECT VERIFICATION MODEL", "Select a finite-state model", Store.Models.Where(m => Active(m.Status)).OrderByDescending(m => m.UpdatedUtc ?? m.CreatedUtc).Cast<object>().ToList()) as VerificationModel; }
        private static void Touch(VerificationModel model) { model.Revision = Math.Max(1, model.Revision) + 1; model.UpdatedUtc = Now(); }
        private static IEnumerable<string> EvidenceForTrace(VerificationModel model, VerificationRun run) { if (model == null || run == null) return Enumerable.Empty<string>(); List<string> ids = new List<string>(); ids.AddRange(model.EvidenceNodeIds); foreach (string stateId in run.TraceStateIds) { VerificationState state = State(model, stateId); if (state != null) ids.AddRange(state.EvidenceNodeIds); } foreach (string transitionId in run.TraceTransitionIds) { VerificationTransition transition = Transition(model, transitionId); if (transition != null) ids.AddRange(transition.EvidenceNodeIds); } return ids.Where(x => !String.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase); }
        private static List<VerificationTraceRow> TraceRows(VerificationModel model, VerificationRun run) { List<VerificationTraceRow> rows = new List<VerificationTraceRow>(); if (model == null || run == null) return rows; for (int i = 0; i < run.TraceStateIds.Count; i++) { rows.Add(new VerificationTraceRow { Index = i, State = State(model, run.TraceStateIds[i]) }); if (i < run.TraceTransitionIds.Count) rows.Add(new VerificationTraceRow { Index = i, Transition = Transition(model, run.TraceTransitionIds[i]) }); } return rows; }
