        private static string DescribeWorldNode(WorldNode node) { StringBuilder s = new StringBuilder(); s.AppendLine("WORLD OBJECT ID    " + node.Id); s.AppendLine("KIND               " + node.Kind); s.AppendLine("LABEL              " + node.Label); s.AppendLine("EVIDENCE CLASS     " + node.EvidenceClass); s.AppendLine("SOURCE             " + node.SourcePath); s.AppendLine("JSON PATH          " + node.JsonPath); s.AppendLine("FINGERPRINT        " + node.Fingerprint); s.AppendLine(); s.AppendLine(node.Summary ?? ""); return s.ToString(); }
        private static string TheoryProjectionFingerprint(LogicTheory theory, Dictionary<string, string> truth) { StringBuilder s = new StringBuilder(); s.Append(theory == null ? "" : theory.Id).Append('|').Append(theory == null ? "" : theory.WorldId).Append('|').Append(theory == null ? "" : theory.Name).Append('|').Append(theory == null ? "" : theory.Status).Append('\n'); if (theory != null) { foreach (string id in (theory.FactIds ?? new List<string>()).OrderBy(x => x, StringComparer.OrdinalIgnoreCase)) s.Append("F:").Append(id).Append('\n'); foreach (string id in (theory.RuleIds ?? new List<string>()).OrderBy(x => x, StringComparer.OrdinalIgnoreCase)) s.Append("R:").Append(id).Append('\n'); } foreach (KeyValuePair<string, string> row in (truth ?? new Dictionary<string, string>()).OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase)) s.Append("Q:").Append(row.Key).Append('=').Append(row.Value).Append('\n'); return HashText(s.ToString()); }
        private static string ResolutionProjectionFingerprint(CivilResolution resolution) { if (resolution == null) return HashText("null-resolution"); StringBuilder s = new StringBuilder(); s.Append(resolution.Id).Append('|').Append(resolution.Title).Append('|').Append(resolution.Proposition).Append('|').Append(resolution.EpistemicClass).Append('|').Append(resolution.Status).Append('\n'); foreach (string id in (resolution.EvidenceNodeIds ?? new List<string>()).OrderBy(x => x, StringComparer.OrdinalIgnoreCase)) s.Append("E:").Append(id).Append('\n'); return HashText(s.ToString()); }
        private static List<string> SplitRows(string raw) { return (raw ?? "").Replace("\r", "").Split(new[] { '\n', ';' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Take(1024).ToList(); }
        private static string NormalizeSymbol(string value) { return new string((value ?? "").Trim().ToLowerInvariant().Select(c => Char.IsLetterOrDigit(c) || c == '_' || c == '-' ? c : '_').ToArray()); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<TItem> TakeLastLocal<TItem>(IEnumerable<TItem> source, int count) { if (source == null) yield break; Queue<TItem> queue = new Queue<TItem>(); foreach (TItem item in source) { queue.Enqueue(item); if (queue.Count > count) queue.Dequeue(); } foreach (TItem item in queue) yield return item; }

