        private sealed class DslTransition { public int Line; public string Name; public string From; public string To; public string Kind; public string Guard; public string Action; public string Fairness; }
        private sealed class VerificationTraceRow { public int Index; public VerificationState State; public VerificationTransition Transition; public override string ToString() { if (State != null) return Index.ToString(CultureInfo.InvariantCulture).PadLeft(4) + "   STATE       " + State.Name + "   ·   " + String.Join(", ", State.Labels.Take(10).ToArray()); return "       TRANSITION  └─ " + (Transition == null ? "∅" : Transition.Name + "   [" + Transition.Kind + "]"); } }
        private sealed class VerificationAuditFinding { public string Severity; public string Code; public string SubjectId; public string Detail; public string NodeId; public override string ToString() { return (Severity ?? "INFO").PadRight(5) + "   ·   " + (Code ?? "AUDIT").PadRight(32) + "   ·   " + (SubjectId ?? "∅") + "   ·   " + (Detail ?? ""); } }
